 * The search starts from each task in ascending name order and walks each task's
 * dependencies in ascending name order; the cycle runs from the task the search
 * re-entered, through the stack, back to that task.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[] | undefined} the cycle's names, the repeat included.
 */
export function findCycle(tasks) {
  const COLOR = { WHITE: 0, GRAY: 1, BLACK: 2 }
  const color = new Map()
  const stack = []

  const visit = (name) => {
    color.set(name, COLOR.GRAY)
    stack.push(name)

    const task = tasks.get(name)
    if (task) {
      // Visit dependencies in ascending order
      for (const dep of [...task.needs].sort()) {
        const depColor = color.get(dep) ?? COLOR.WHITE

        if (depColor === COLOR.GRAY) {
          // Found a cycle: extract it from the stack
          const startIndex = stack.findIndex(n => n === dep)
          const cycle = stack.slice(startIndex)
          cycle.push(dep) // Add the repeat at the end
          return cycle
        }

        if (depColor === COLOR.WHITE) {
          const cycleResult = visit(dep)
          if (cycleResult) return cycleResult
        }
      }
    }

    stack.pop()
    color.set(name, COLOR.BLACK)
    return undefined
  }

  // Process tasks in ascending order
  for (const taskName of [...tasks.keys()].sort()) {
    const taskColor = color.get(taskName) ?? COLOR.WHITE
    if (taskColor === COLOR.WHITE) {
      const cycle = visit(taskName)
      if (cycle) return cycle
    }
  }

  return undefined
}"}

